sys_variable_value.value:
(function execute(inputs, outputs) {
// Captures the exact system date and time of execution
    var gdt = new GlideDateTime();
    
    // Formats and passes it to the action output
    outputs.current_time = gdt.getValue();
})(inputs, outputs);

